import{_ as n,o as i,c as a,ai as p}from"./chunks/framework.Ai2o9gNv.js";const d=JSON.parse('{"title":"50-拓展-访问规则","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/50-拓展-访问规则/50-拓展-访问规则.md","filePath":"仓颉入门到实战/50-拓展-访问规则/50-拓展-访问规则.md","lastUpdated":1739405272000,"__rawMarkdown":"# 50-拓展-访问规则\\n\\n\\n\\n## 扩展的修饰符\\n\\n扩展本身不能使用修饰符修饰。\\n\\n例如，下面的例子中对 A 的直接扩展前使用了 `public` 修饰，将编译报错。\\n\\n```typescript\\npublic class A {}\\n\\npublic extend A {}  // Error, expected no modifier before extend\\n```\\n\\n扩展成员可使用的修饰符有：`static`、`public`、`protected`、`internal`、`private`、`mut`。\\n\\n- 使用 `private` 修饰的成员只能在本扩展内使用，外部不可见。\\n- 使用 `internal` 修饰的成员可以在当前包及子包（包括子包的子包）内使用，这是默认行为。\\n- 使用 `protected` 修饰的成员在本模块内可以被访问（受导出规则限制）。当被扩展类型是 class 时，该 class 的子类定义体内也能访问。\\n- 使用 `static` 修饰的成员，只能通过类型名访问，不能通过实例对象访问。\\n- 对 `struct` 类型的扩展可以定义 `mut` 函数。\\n\\n```typescript\\npackage p1\\n\\npublic open class A {}\\n\\nextend A {\\n    public func f1() {}\\n    protected func f2() {}\\n    private func f3() {}\\n    static func f4() {}\\n}\\n\\nmain() {\\n    A.f4()\\n    var a = A()\\n    a.f1()\\n    a.f2()\\n}\\n```\\n\\n扩展内的成员定义不支持使用 `open`、`override`、`redef` 修饰。\\n\\n```typescript\\nclass Foo {\\n    public open func f() {}\\n    static func h() {}\\n}\\n\\nextend Foo {\\n    public override func f() {} // Error\\n    public open func g() {} // Error\\n    redef static func h() {} // Error\\n}\\n```\\n\\n## 扩展的孤儿规则\\n\\n为一个其它 `package` 的类型实现另一个 `package` 的接口，可能造成理解上的困扰。\\n\\n为了防止一个类型被意外实现不合适的接口，仓颉不允许定义孤儿扩展，指的是既不与接口（包含接口继承链上的所有接口）定义在同一个包中，也不与被扩展类型定义在同一个包中的接口扩展。\\n\\n如下代码所示，不能在 `package c` 中，为 `package a` 里的 `Foo` 实现 `package b` 里的 `Bar`。\\n\\n只能在 `package a` 或者在 `package b` 中为 `Foo` 实现 `Bar`。\\n\\n```typescript\\n// package a\\npublic class Foo {}\\n\\n// package b\\npublic interface Bar {}\\n\\n// package c\\nimport a.Foo\\nimport b.Bar\\n\\nextend Foo <: Bar {} // Error\\n```\\n\\n## 扩展的访问和遮盖\\n\\n扩展的实例成员与类型定义处一样可以使用 `this`，`this` 的功能保持一致。同样也可以省略 `this` 访问成员。扩展的实例成员不能使用 `super`。\\n\\n```typescript\\nclass A {\\n    var v = 0\\n}\\n\\nextend A {\\n    func f() {\\n        print(this.v) // Ok\\n        print(v) // Ok\\n    }\\n}\\n```\\n\\n扩展不能访问被扩展类型中 `private` 修饰的成员。\\n\\n```typescript\\nclass A {\\n    private var v1 = 0\\n    protected var v2 = 0\\n}\\n\\nextend A {\\n    func f() {\\n        print(v1) // Error\\n        print(v2) // Ok\\n    }\\n}\\n```\\n\\n扩展不能遮盖被扩展类型的任何成员。\\n\\n```typescript\\nclass A {\\n    func f() {}\\n}\\n\\nextend A {\\n    func f() {} // Error\\n}\\n```\\n\\n扩展也不允许遮盖其它扩展增加的任何成员。\\n\\n```typescript\\nclass A {}\\n\\nextend A {\\n    func f() {}\\n}\\n\\nextend A {\\n    func f() {} // Error\\n}\\n```\\n\\n在同一个包内，对同一类型可以扩展多次，并且在扩展中可以直接调用被扩展类型的其他扩展中非 `private` 修饰的函数。\\n\\n```typescript\\nclass Foo {}\\n\\nextend Foo { // OK\\n    private func f() {}\\n    func g() {}\\n}\\n\\nextend Foo { // OK\\n    func h() {\\n        g() // OK\\n        f() // Error\\n    }\\n}\\n```\\n\\n扩展泛型类型时，可以使用额外的泛型约束。泛型类型的任意两个扩展之间的可见性规则如下：\\n\\n- 如果两个扩展的约束相同，则两个扩展相互可见，即两个扩展内可以直接使用对方内的函数或属性；\\n- 如果两个扩展的约束不同，且两个扩展的约束有包含关系，约束更宽松的扩展对约束更严格的扩展可见，反之，不可见；\\n- 当两个扩展的约束不同时，且两个约束不存在包含关系，则两个扩展均互相不可见。\\n\\n示例：假设对同一个类型 `E<X>` 的两个扩展分别为扩展 `1` 和扩展 `2` ，`X` 的约束在扩展 `1` 中比扩展 `2` 中更严格，那么扩展 `1` 中的函数和属性对扩展 `2` 均不可见，反之，扩展 `2` 中的函数和属性对扩展 `1` 可见。\\n\\n```typescript\\nopen class A {}\\nclass B <: A {}\\nclass E<X> {}\\n\\ninterface I1 {\\n    func f1(): Unit\\n}\\ninterface I2 {\\n    func f2(): Unit\\n}\\n\\nextend<X> E<X> <: I1 where X <: B {  // extension 1\\n    public func f1(): Unit {\\n        f2() // OK\\n    }\\n}\\n\\nextend<X> E<X> <: I2 where X <: A   { // extension 2\\n    public func f2(): Unit {\\n        f1() // Error\\n    }\\n}\\n```\\n\\n## 扩展的导入导出\\n\\n扩展也是可以被导入和导出的，但是扩展本身不能使用 `public` 修饰，扩展的导出有一套特殊的规则。\\n\\n对于直接扩展，只有当扩展与被扩展的类型在同一个包中，并且被扩展的类型和扩展中添加的成员都使用 `public` 或 `protected` 修饰时，扩展的功能才会被导出。\\n\\n除此以外的直接扩展均不能被导出，只能在当前包使用。\\n\\n如以下代码所示，`Foo` 是使用 `public` 修饰的类型，并且 `f` 与 `Foo` 在同一个包内，因此 `f` 会跟随 `Foo` 一起被导出。而 `g` 和 `Foo` 不在同一个包，因此 `g` 不会被导出。\\n\\n```typescript\\n// package a\\n\\npublic class Foo {}\\n\\nextend Foo {\\n    public func f() {}\\n}\\n\\n// package b\\nimport a.*\\n\\nextend Foo {\\n    public func g() {}\\n}\\n\\n// package c\\nimport a.*\\nimport b.*\\n\\nmain() {\\n    let a = Foo()\\n    a.f() // OK\\n    a.g() // Error\\n}\\n```\\n\\n对于接口扩展则分为两种情况：\\n\\n1. 如果接口扩展和被扩展类型在同一个包，但接口是来自导入的，只有当被扩展类型使用 `public` 修饰时，扩展的功能才会被导出。\\n2. 如果接口扩展与接口在同一个包，则只有当接口是使用 `public` 修饰时，扩展的功能才会被导出。\\n\\n如下代码所示，`Foo` 和 `I` 都使用了 `public` 修饰，因此对 `Foo` 的扩展就可以被导出。\\n\\n```typescript\\n// package a\\n\\npublic class Foo {}\\n\\npublic interface I {\\n    func g(): Unit\\n}\\n\\nextend Foo <: I {\\n    public func g(): Unit {}\\n}\\n\\n// package b\\nimport a.*\\n\\nmain() {\\n    let a: I = Foo()\\n    a.g()\\n}\\n```\\n\\n与扩展的导出类似，扩展的导入也不需要显式地用 `import` 导入，扩展的导入只需要导入被扩展的类型和接口，就可以导入可访问的所有扩展。\\n\\n如下面的代码所示，在 `package b` 中，只需要导入 `Foo` 就可以使用 `Foo` 对应的扩展中的函数 `f`。\\n\\n而对于接口扩展，需要同时导入被扩展的类型和扩展的接口才能使用，因此在 `package c` 中，需要同时导入 `Foo` 和 `I` 才能使用对应扩展中的函数 `g`。\\n\\n```typescript\\n// package a\\npublic class Foo {}\\nextend Foo {\\n    public func f() {}\\n}\\n\\n// package b\\nimport a.Foo\\n\\npublic interface I {\\n    func g(): Unit\\n}\\nextend Foo <: I {\\n    public func g() {\\n        this.f() // OK\\n    }\\n}\\n\\n// package c\\nimport a.Foo\\nimport b.I\\n\\nfunc test() {\\n    let a = Foo()\\n    a.f() // OK\\n    a.g() // OK\\n}\\n```"}'),l={name:"仓颉入门到实战/50-拓展-访问规则/50-拓展-访问规则.md"};function e(h,s,t,k,r,c){return i(),a("div",null,[...s[0]||(s[0]=[p("",45)])])}const b=n(l,[["render",e]]);export{d as __pageData,b as default};
